// ---- Derived helpers ----

export interface FlatModel extends TruckModel {
  make: string;
  makeColor: string;
  makeColor2: string;
  parent: string;
  id: string;
}

export const ALL_MODELS: FlatModel[] = TRUCK_MAKES.flatMap((mk) =>
  mk.models.map((m) => ({
    ...m,
    make: mk.make,
    makeColor: mk.color,
    makeColor2: mk.color2,
    parent: mk.parent,
    id: `${mk.make}-${m.model}`.toLowerCase().replace(/[^a-z0-9]+/g, "-"),
  })),
);

export const MAKE_NAMES: string[] = TRUCK_MAKES.map((m) => m.make);

export const BODY_TYPES: BodyType[] = Array.from(
  new Set(ALL_MODELS.map((m) => m.bodyType)),
);

export const ALL_CLASSES: number[] = Array.from(
  new Set(ALL_MODELS.flatMap((m) => m.classes)),
).sort((a, b) => a - b);

export const TRUCK_STATS = {
  makes: TRUCK_MAKES.length,
  models: ALL_MODELS.length,
  engines: Array.from(new Set(ALL_MODELS.flatMap((m) => m.engines))).length,
  oldest: Math.min(...TRUCK_MAKES.map((m) => m.founded)),
};

/** Catalog deep-link for a given model (the marketplace lives on partsnow.ai). */
export function partsHref(make: string, model: string): string {
  return `https://partsnow.ai/products?vehicle=${encodeURIComponent(`${make} ${model}`)}`;
}

/** A natural-language question to seed Mike's chat for a model. Mike on this
 * site is diagnosis-only (no catalog access), so the seed asks for help
 * figuring out the problem — not for prices or stock. */
export function askMikePrompt(make: string, model: string): string {
  return `I've got a ${cleanMakeName(make)} ${model} and something's not right. Can you help me figure out what's wrong and which part I need?`;
}

// ---- URL slugs (per-truck SEO pages) ----

/** Make name without the "(legacy)" / "(Chassis Cab)" status annotation. */
export function cleanMakeName(make: string): string {
  return make.replace(/\s*\([^)]*\)\s*/g, " ").replace(/\s+/g, " ").trim();
}

function slugify(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
}

/** URL slug for a make hub page, e.g. "Mitsubishi Fuso (legacy)" -> "mitsubishi-fuso". */
export function makeSlug(make: string): string {
  return slugify(cleanMakeName(make));
}

/** URL slug for a model within a make, e.g. "DuraStar (4300/4400)" -> "durastar-4300-4400". */
export function modelSlug(model: string): string {
  return slugify(model);
}

/** Canonical path for a model's dedicated page. */
export function truckModelHref(make: string, model: string): string {
  return `/trucks/${makeSlug(make)}/${modelSlug(model)}`;
}

/** Canonical path for a make hub page. */
export function truckMakeHref(make: string): string {
  return `/trucks/${makeSlug(make)}`;
}

/** Whether a make is a discontinued / parts-only brand (annotated "(legacy)"/"(defunct)"). */
export function isLegacyMake(make: string): boolean {
  return /\((legacy|discontinued|defunct)\)/i.test(make);
}

/** Resolve a make from its slug. */
export function findMakeBySlug(slug: string): TruckMake | undefined {
  return TRUCK_MAKES.find((mk) => makeSlug(mk.make) === slug);
}

/** Resolve a model from its make + model slugs. */
export function findModelBySlugs(
  makeSlugStr: string,
  modelSlugStr: string,
): FlatModel | undefined {
  return ALL_MODELS.find(
    (m) => makeSlug(m.make) === makeSlugStr && modelSlug(m.model) === modelSlugStr,
  );
}

/** All models belonging to a make. */
export function modelsForMake(make: string): FlatModel[] {
  return ALL_MODELS.filter((m) => m.make === make);
}
